    def _set_project_name(self) -> bool:
        """
        Determines and sets the project name to use based on the user input, current
        configuration and force flag.

        Returns:
            bool: a boolean indicating whether the configuration file needs updating.
        """
        # Case 1: Project name was provided by the user at construction time
        if self.project_name is not None:
            return True if self.force else False

        # Case 2: Use project name from the current configuration if it is a
        # non-default, non-empty value and we are not forced to change it
        if (
            self.current_config.project_name
            and self.current_config.project_name != OPIK_PROJECT_DEFAULT_NAME
            and not self.force
        ):
            self.project_name = self.current_config.project_name
            return False

        # Case 3: No usable project name, default to OPIK_PROJECT_DEFAULT_NAME
        use_default_project_name = (
            True
            if self.automatic_approvals
            else ask_user_for_approval(
                f'Do you want to use "{OPIK_PROJECT_DEFAULT_NAME}" project? (Y/n)'
            )
        )

        if use_default_project_name:
            self.project_name = OPIK_PROJECT_DEFAULT_NAME
        else:
            self._ask_for_project_name()

        return True

    def _ask_for_project_name(self) -> None:
        """
        Prompt the user for an Opik project name.

        Raises:
            ConfigurationError: Raised if the user enters an empty project name.
        """
        self.project_name = input("Please enter your project name: ")

        if not self.project_name:
            raise ConfigurationError("The project name cannot be empty")

